const item = $input.first()?.json || {};
const req = $('Prism Intent Request Webhook').first()?.json || {};
const raw = String(item.output || item.text || '');
let parsed = {
  intent: 'CHAT',
  reasoning: 'Fallback: unparseable model output - defaulted to CHAT so the conversation continues.',
  connectorId: null,
  topics: [],
  requestedAction: null
};
const cleaned = raw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
try {
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start >= 0 && end > start) {
    const candidate = JSON.parse(cleaned.slice(start, end + 1));
    if (candidate && typeof candidate === 'object') { parsed = Object.assign(parsed, candidate); }
  }
} catch (e) { /* keep fallback intent */ }
const validConnectors = ['microsoft.outlook','microsoft.sharepoint','microsoft.dynamics','zoho.crm','zoho.projects','zoho.books','internal.kb'];
if (parsed.connectorId && validConnectors.indexOf(parsed.connectorId) < 0) { parsed.connectorId = null; }
return [{ json: {
  ok: true,
  status: 'success',
  intent: parsed.intent,
  reasoning: parsed.reasoning || null,
  connectorId: parsed.connectorId || null,
  topics: Array.isArray(parsed.topics) ? parsed.topics : [],
  requestedAction: parsed.requestedAction || null,
  organizationId: req.body?.organizationId || req.organizationId || null,
  userId: req.body?.userId || req.userId || null,
  diagnostics: { requestId: 'int-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-02-intent-router', model: 'gemini-3.7-flash' }
} }];
